SELECT jo.job_no, jo.dispatch_status, jo.priority, jo.equipment_id, COALESCE(jo.segment_id, '') AS segment_id, COALESCE(wr.product_definition_id, '') AS product_definition_id, wr.quantity, COALESCE(wr.uom, '') AS uom, jo.planned_start FROM emc_job_order jo JOIN emc_work_request wr ON wr.request_id = jo.request_id WHERE (? = '' OR jo.equipment_id = ?) AND jo.dispatch_status NOT IN ('ENDED', 'ABORTED', 'CANCELLED') ORDER BY jo.priority, jo.planned_start
